import React, { useState } from 'react';
import { FaFilePdf, FaPercentage, FaPiggyBank, FaHandHoldingUsd } from 'react-icons/fa';
import './InterestRate.css';

const InterestRate = () => {
    const [activeTab, setActiveTab] = useState('loans');

    // Data extracted directly from the uploaded notice [cite: 10, 12, 19]
    const baseRate = "12.52%"; 
    const effectiveDate = "2082/09/30";
    const period = "Magh 1, 2082 to Chaitra End, 2082";

    const loanRates = [
        { sn: 1, name: "General Loan (साधारण कर्जा)", variable: "Base Rate + 1.86%", fixed: "14.38%" },
        { sn: 2, name: "Seasonal Loan (मौसमी कर्जा)", variable: "Base Rate + 1.86%", fixed: "14.38%" },
        { sn: 3, name: "Micro-Enterprise Loan (लघुउद्यम कर्जा)", variable: "Base Rate + 1.86%", fixed: "14.38%" },
        { sn: 4, name: "Alternative Energy Loan", variable: "Base Rate + 1.86%", fixed: "14.38%" },
        { sn: 5, name: "Foreign Employment Loan", variable: "Base Rate + 1.86%", fixed: "14.38%" },
        { sn: 6, name: "Infinity Samriddhi/Digital Loan", variable: "Base Rate + 1.86%", fixed: "14.38%" },
    ];

    const savingRates = [
        { sn: 1, name: "Asal Bachat (असल वचत)", rate: "7.2%" },
        { sn: 2, name: "Individual/Group/Daily Bachat", rate: "7.2%" },
        { sn: 3, name: "Special Bachat (विशेष बचत)", rate: "7.5%" },
        { sn: 4, name: "Infinity Surakshya Bachat", rate: "7.2%" },
        { sn: 5, name: "Infinity Sunaulo Bhawishya", rate: "7.99%" },
    ];

    return (
        <div className="rate-container">
            {/* Hero Section */}
            <div className="rate-hero">
                <h1>Interest Rates</h1>
                <p>Effective Period: {period}</p>
                <div className="base-rate-badge">
                    Average Base Rate (Ashwin - Mangsir): <strong>{baseRate}</strong>
                </div>
            </div>

            <div className="rate-content-wrapper">
                {/* Tab Navigation */}
                <div className="rate-tabs">
                    <button 
                        className={activeTab === 'loans' ? 'active' : ''} 
                        onClick={() => setActiveTab('loans')}
                    >
                        <FaHandHoldingUsd /> Loan Rates
                    </button>
                    <button 
                        className={activeTab === 'savings' ? 'active' : ''} 
                        onClick={() => setActiveTab('savings')}
                    >
                        <FaPiggyBank /> Savings Rates
                    </button>
                </div>

                {/* Table Section */}
                <div className="table-responsive">
                    {activeTab === 'loans' ? (
                        <table className="custom-table">
                            <thead>
                                <tr>
                                    <th>S.N.</th>
                                    <th>Product Description</th>
                                    <th>Variable (Base + Premium)</th>
                                    <th>Fixed Rate</th>
                                </tr>
                            </thead>
                            <tbody>
                                {loanRates.map((loan) => (
                                    <tr key={loan.sn}>
                                        <td>{loan.sn}</td>
                                        <td>{loan.name}</td>
                                        <td className="text-blue">{loan.variable}</td>
                                        <td className="text-green">{loan.fixed}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    ) : (
                        <table className="custom-table">
                            <thead>
                                <tr>
                                    <th>S.N.</th>
                                    <th>Savings Product</th>
                                    <th>Interest Rate (p.a.)</th>
                                </tr>
                            </thead>
                            <tbody>
                                {savingRates.map((save) => (
                                    <tr key={save.sn}>
                                        <td>{save.sn}</td>
                                        <td>{save.name}</td>
                                        <td className="text-green">{save.rate}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    )}
                </div>

                {/* Footer Notice  */}
                <div className="rate-footer-info">
                    <p><strong>Note:</strong> 1% interest subsidy is provided to Dalits, conflict victims, single women, and senior citizens upon submission of government certification.</p>
                    <a href="/assets/pdf/2082m.pdf" target="_blank" className="download-full-btn">
                        <FaFilePdf /> Download Full Notice (PDF)
                    </a>
                </div>
            </div>
        </div>
    );
};

export default InterestRate;
